    10	
    11	/**
    12	 * Submit form to update user's first and last legal name
    13	 * @param values - form input values
    14	 */
    15	function updateAddress(values: FormOnyxValues<typeof ONYXKEYS.FORMS.HOME_ADDRESS_FORM>) {
    16	    updateAddressPersonalDetails(
    17	        values.addressLine1?.trim() ?? '',
    18	        values.addressLine2?.trim() ?? '',
    19	        values.city.trim(),
    20	        values.state.trim(),
    21	        values?.zipPostCode?.trim().toUpperCase() ?? '',
    22	        values.country,
    23	    );
    24	}
    25	
    26	function PersonalAddressPage() {
    27	    const {translate} = useLocalize();
    28	    const [privatePersonalDetails] = useOnyx(ONYXKEYS.PRIVATE_PERSONAL_DETAILS);
    29	    const [isLoadingApp] = useOnyx(ONYXKEYS.IS_LOADING_APP);
    30	    const address = useMemo(() => getCurrentAddress(privatePersonalDetails), [privatePersonalDetails]);
    31	    const defaultCountry = getDefaultCountry();
