    33	    return (
    34	        <AddressPage
    35	            defaultCountry={defaultCountry as Country}
    36	            address={address}
    37	            isLoadingApp={isLoadingApp}
    38	            updateAddress={updateAddress}
    39	            title={translate('privatePersonalDetails.address')}
    40	        />
    41	    );
    42	}
    43	
    44	PersonalAddressPage.displayName = 'PersonalAddressPage';
    45	
    46	export default PersonalAddressPage;
